use num_bigint::BigUint;
use syn::Block;
type Exp = u128;
struct BlockSimulator {
    pub left_tape: Vec<BlockSymbol>,
    pub right_tape: Vec<BlockSymbol>,
    pub state: HigherState,
    pub base_steps: BigUint,
    pub self_steps: u64,
    pub accelerate_bells: bool,
}
impl fmt::Display for BlockSymbol {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use BlockSymbol::*;
        let s0 = match *self {
            Run(t, _) => &format!("{:?}", t),
            _ => &format!("{:?}", self),
        };
        let s_exp = match *self {
            Run(_, n) => {
                if n == 1 {
                    ""
                } else {
                    &format!("^{}", n)
                }
            }
            _ => "",
        };
        write!(f, "{}{}", s0, s_exp)
    }
}

// End of customizable code

impl BlockSimulator {
    fn new(accelerate_bells: bool) -> Self {
        use BlockSymbol::*;
        Self {
            left_tape: vec![L],
            right_tape: vec![R],
            state: HigherState::Left,
            base_steps: BigUint::from(3u8),
            self_steps: 0,
            accelerate_bells,
        }
    }

    fn bell_step(&mut self) -> Option<Result<BigUint, SimError>> {
        use BlockSymbol::*;
        use HigherState::*;
        use RunSymbolType::*;

        if self.state != Right {
            return None;
        }

        let u_k = match self.left_tape.as_slice() {
            [L] => 0,
            [L, Run(U, n)] => *n,
            _ => return None,
        };

        let mut right_sl = self.right_tape.as_slice();
        let y_k = match right_sl {
            [rest @ .., Run(Y, n)] => {
                let k = *n;
                right_sl = rest;
                k
            }
            _ => 0,
        };

        let (n_heads, right_steps, y_k_new) = match right_sl {
            // y^3n Y^k J^2n -> Y^k+3n
            [.., Run(J, m @ 2..)] => {
                let n = m / 2;
                if y_k > 0 {
                    self.right_tape.pop();
                }
                decrease_run_by(&mut self.right_tape, J, 2 * n);
                // n(30k + 45n + 17)
                let nb = BigUint::from(n);
                let nb45 = nb.clone() * 45u8;
                let s = (BigUint::from(y_k) * 30u8 + &nb45 + 17u8) * &nb;
                (3 * n, s, y_k + 3 * n)
            }
            // y^n Y^k F^4n -> Y^k+n
            [.., Run(F, m @ 4..)] => {
                let n = m / 4;
                if y_k > 0 {
                    self.right_tape.pop();
                }
                decrease_run_by(&mut self.right_tape, F, 4 * n);
                // 5 * n * (2 * y_k + n + 1)
                let nb = BigUint::from(n);
                let s = (BigUint::from(y_k) * 2u8 + &nb + 1u8) * &nb * 5u8;
                (n, s, y_k + n)
            }
            // y^2n Y^k J Y^n -> Y^k+n J
            [.., Run(Y, n0 @ 1..), Run(J, 1)] => {
                let n = *n0;
                if y_k > 0 {
                    self.right_tape.pop();
                }
                self.right_tape.pop();
                self.right_tape.pop();
                add_or_merge_run(&mut self.right_tape, J, 1);
                // n * ((y_k * 2 + n) * 10 + 26)
                let nb = BigUint::from(n);
                let s = ((BigUint::from(y_k) * 2u8 + &nb) * 10u8 + 26u8) * &nb;
                (2 * n, s, y_k + n)
            }
            _ => return None,
        };
        add_or_merge_run(&mut self.right_tape, Y, y_k_new);

        let nb = BigUint::from(n_heads);
        let left_steps = (BigUint::from(u_k) * 2u8 + &nb + 1u8) * &nb * 5u8;
        add_or_merge_run(&mut self.left_tape, U, n_heads);

        Some(Ok(left_steps + right_steps))
    }

    fn multi_shift_step(&mut self) -> Option<Result<Exp, SimError>> {
        use BlockSymbol::*;
        use HigherState::*;
        use RunSymbolType::*;
        let n_steps = match (
            &self.state,
            self.left_tape.as_slice(),
            self.right_tape.as_slice(),
        ) {
            // > Y -> V V >
            (Right, _, [.., Run(Y, n0)]) => {
                let n = *n0;
                self.right_tape.pop();
                add_or_merge_run(&mut self.left_tape, V, 2u128 * n);
                4u128 * n
            }
            // V V < -> < Y
            (Left, [.., Run(V, m @ 2u128..)], _) => {
                let n = m / 2;
                decrease_run_by(&mut self.left_tape, V, 2u128 * n);
                add_or_merge_run(&mut self.right_tape, Y, 1u128 * n);
                6u128 * n
            }
            // U U <c -> <c J (1/2)
            (LeftChange, [.., Run(U, m @ 2u128..)], _) => {
                let n = m / 2;
                decrease_run_by(&mut self.left_tape, U, 2u128 * n);
                add_or_merge_run(&mut self.right_tape, J, 1u128 * n);
                62u128 * n
            }
            // V <w -> <w F F
            (LeftWide, [.., Run(V, n0)], _) => {
                let n = *n0;
                self.left_tape.pop();
                add_or_merge_run(&mut self.right_tape, F, 2u128 * n);
                26u128 * n
            }
            _ => return None,
        };
        Some(Ok(n_steps))
    }

    fn step(&mut self) -> Result<(), SimError> {
        use BlockSymbol::*;
        use HigherState::*;
        use RunSymbolType::*;

        let new_base_steps = if matches!(
            (&self.state, self.right_tape.as_slice(),),
            (Left | Right, [.., Q, Run(F, 3u128)])
        ) {
            // < F F F Q -> < Y
            self.right_tape.pop();
            self.right_tape.pop();
            add_or_merge_run(&mut self.right_tape, Y, 1u128);
            BigUint::ZERO
        } else if matches!(
            (&self.state, self.right_tape.as_slice()),
            (Left | LeftChange, [.., Q, Run(F, 1), Run(Y, 1), Run(J, 1)])
        ) {
            // < J Y F Q -> < J J
            // <c J Y F Q -> <c J J
            self.right_tape.pop();
            self.right_tape.pop();
            self.right_tape.pop();
            self.right_tape.pop();
            add_or_merge_run(&mut self.right_tape, J, 2u128);
            BigUint::ZERO
        } else if self.accelerate_bells
            && let Some(res) = self.bell_step()
        {
            res?
        } else if let Some(res) = self.multi_shift_step() {
            BigUint::from(res?)
        } else {
            BigUint::from(self.basic_step()?)
        };
        self.base_steps += new_base_steps;
        self.self_steps += 1;
        Ok(())
    }
}

enum LeftResult {
    Right,
    RightFQ,
    RightQ,
    RightJQ,
    RightJ,
}

impl fmt::Display for LeftResult {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self {
            LeftResult::Right => write!(f, ">"),
            LeftResult::RightFQ => write!(f, ">FQ"),
            LeftResult::RightQ => write!(f, ">Q"),
            LeftResult::RightJQ => write!(f, ">JQ"),
            LeftResult::RightJ => write!(f, ">J"),
        }
    }
}

fn run_left_sim(mut sim: BlockSimulator, verbose: bool) -> (u64, LeftResult, BlockSimulator) {
    use BlockSymbol::*;
    use RunSymbolType::*;

    if verbose {
        println!("{sim}");
    }
    loop {
        if sim.state == HigherState::Right && sim.right_tape.is_empty() {
            return (sim.self_steps, LeftResult::Right, sim);
        } else if sim.state == HigherState::Right
            && matches!(sim.right_tape.as_slice(), [Q, Run(F, 1)])
        {
            return (sim.self_steps, LeftResult::RightFQ, sim);
        } else if sim.state == HigherState::Right && matches!(sim.right_tape.as_slice(), [Q]) {
            return (sim.self_steps, LeftResult::RightQ, sim);
        } else if sim.state == HigherState::Right
            && matches!(sim.right_tape.as_slice(), [Q, Run(J, 1)])
        {
            return (sim.self_steps, LeftResult::RightJQ, sim);
        } else if sim.state == HigherState::Right
            && matches!(sim.right_tape.as_slice(), [Run(J, 1)])
        {
            return (sim.self_steps, LeftResult::RightJ, sim);
        }
        let res = sim.step();

        if verbose {
            println!("{sim}");
        }

        if let Err(e) = res {
            println!("{e}");
            panic!();
        }
    }
}

